entries.example:
on break:
    if player does not have permission "builder":
        cancel event

on chat:
    if message is "help":
        send "Try /rules" to player

on damage of zombie:
    if attacker is a player:
        add 2 to damage

on drop:
    if event-item is diamond:
        cancel event

on inventory click:
    if clicked slot is 4:
        cancel event

on level change:
    if new level > old level:
        send "level up!" to player

on load:
    if {spawn} is not set:
        set {spawn} to location(0, 64, 0)

on move:
    if y of event-location < 0:
        teleport player to spawn of world "world"

on placeholder request for prefix "shop":
    if the identifier is "coins":
        set the result to "%{coins::%player%} ? 0%"

on sneak toggle:
    if player is sneaking:
        send "standing up" to player

on damage of player:
    if damage > 6:
        set damage to 6

on death:
    if attacker is a zombie:
        set death message to "&c%player% was eaten"

loop 10 times:
    if loop-number is 5:
        exit loop

if {coins::%uuid of player%} >= 10:
    send "rich" to player
else:
    send "poor" to player

set {n} to 5
reset {n}
set {l::*} to 1, 2, 1 and 3
remove all 1 from {l::*}

set {_i} to 0
while {_i} < 5:
    add 1 to {_i}

spawn a cow at location(0, 70, 0)
if last spawned entity can age:
    send "yes"

on damage:
    if damage was caused by fall:
        cancel event

on throwing of an egg:
    if the egg will hatch:
        send "A chick!" to player

on chat:
    if message ends with "?":
        send "good question" to player

on join:
    if player hasn't played before:
        send "Welcome, new player!" to player

set {_gui} to chest inventory
if {_gui} contains 2 diamonds:
    send "yes" to player

on respawn:
    if the respawn location is a bed spawn:
        send "welcome back"

set {_e} to potion effect of speed for 10 seconds
if {_e} is infinite:
    send "forever"

spawn an interaction at player
if last spawned entity is responsive:
    send "yes"

on join:
    if stone is tagged with minecraft tag "base_stone_overworld":
        send "stone"

on resource pack response:
    if the resource pack was declined:
        send "Please accept the pack" to player

on chat:
    if message starts with "!":
        cancel event

on chat:
    if message contains "hello":
        send "hi!" to player

on join:
    if chunk of player is loaded:
        send "loaded"

loop blocks in radius 3 of player:
    if type of block at loop-value is stone:
        set block at loop-value to glass

set {_b} to boss bar with id "raid"
if {_b} is set:
    show bossbar {_b} to player

on right click:
    if clicked block is chest:
        send "a chest" to player

on death:
    if the zombie is set:
        broadcast "a zombie fell"

on damage:
    if attacker is a player:
        send "%attacker% hit you for %damage%" to victim

on mob spawn:
    if event-entity is a creeper:
        cancel event

on inventory click:
    if name of event-inventory is "Shop":
        cancel event

on projectile hit:
    if hit player is set:
        send "ouch" to hit player

on inventory click:
    if inventory action is "pickup all":
        cancel event

set {_i} to chest inventory with 3 rows named "Shop"
add player to viewers of {_i}
send "%viewers of {_i}%"

set {_v} to vector(1, 2, 3)
set x of {_v} to 5
add 2 to y of {_v}
